-- Esquema oficial para PostgreSQL.
-- Uso: psql -U admin -d postgres -f db/schema.postgres.sql
--
-- Los identificadores usan GENERATED BY DEFAULT AS IDENTITY para permitir
-- importar los IDs históricos de data/*.csv y, a la vez, generar IDs nuevos
-- de forma segura y concurrente.

BEGIN;

CREATE TABLE IF NOT EXISTS dataset (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    name VARCHAR(255) NOT NULL,
    version VARCHAR(255) NOT NULL,
    description VARCHAR(255) NOT NULL,
    status VARCHAR(255) NOT NULL,
    created_at TIMESTAMP NOT NULL,
    PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS languages (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    code VARCHAR(255) NOT NULL,
    name VARCHAR(255) NOT NULL,
    active VARCHAR(255) NOT NULL,
    PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS translation_direction (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    source_language_id BIGINT NOT NULL,
    target_language_id BIGINT NOT NULL,
    active BIGINT NOT NULL,
    PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS language_pair (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    dataset_id BIGINT NOT NULL,
    source_language_id BIGINT NOT NULL,
    target_language_id BIGINT NOT NULL,
    source_text VARCHAR(255) NOT NULL,
    target_text VARCHAR(255) NOT NULL,
    validation_status VARCHAR(255),
    validated_at TIMESTAMP,
    created_at TIMESTAMP NOT NULL,
    PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS model_version (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    name VARCHAR(255) NOT NULL,
    version VARCHAR(255) NOT NULL,
    base_model VARCHAR(255) NOT NULL,
    dataset_id BIGINT NOT NULL,
    status VARCHAR(255) NOT NULL,
    created_at TIMESTAMP NOT NULL,
    PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS evaluation (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    model_version_id BIGINT NOT NULL,
    direction_id BIGINT NOT NULL,
    dataset_id BIGINT NOT NULL,
    bleu DOUBLE PRECISION NOT NULL,
    chr_f DOUBLE PRECISION NOT NULL,
    comet DOUBLE PRECISION NOT NULL,
    evaluation_date TIMESTAMP NOT NULL,
    PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS human_evaluation (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    model_version_id BIGINT NOT NULL,
    direction_id BIGINT NOT NULL,
    sample_direction VARCHAR(255) NOT NULL,
    adequacy_score DOUBLE PRECISION NOT NULL,
    fluency_score DOUBLE PRECISION NOT NULL,
    overall_score DOUBLE PRECISION NOT NULL,
    evaluation_date TIMESTAMP NOT NULL,
    PRIMARY KEY (id)
);

-- Claves foráneas (nombres alineados con entities/models.py)
ALTER TABLE language_pair
    ADD CONSTRAINT fk_language_pair_dataset_id
    FOREIGN KEY (dataset_id) REFERENCES dataset (id);
ALTER TABLE language_pair
    ADD CONSTRAINT fk_language_pair_source_language_id
    FOREIGN KEY (source_language_id) REFERENCES languages (id);
ALTER TABLE language_pair
    ADD CONSTRAINT fk_language_pair_target_language_id
    FOREIGN KEY (target_language_id) REFERENCES languages (id);

ALTER TABLE translation_direction
    ADD CONSTRAINT fk_translation_direction_source_language_id
    FOREIGN KEY (source_language_id) REFERENCES languages (id);
ALTER TABLE translation_direction
    ADD CONSTRAINT fk_translation_direction_target_language_id
    FOREIGN KEY (target_language_id) REFERENCES languages (id);

ALTER TABLE model_version
    ADD CONSTRAINT fk_model_version_dataset_id
    FOREIGN KEY (dataset_id) REFERENCES dataset (id);

ALTER TABLE evaluation
    ADD CONSTRAINT fk_evaluation_model_version_id
    FOREIGN KEY (model_version_id) REFERENCES model_version (id);
ALTER TABLE evaluation
    ADD CONSTRAINT fk_evaluation_direction_id
    FOREIGN KEY (direction_id) REFERENCES translation_direction (id);
ALTER TABLE evaluation
    ADD CONSTRAINT fk_evaluation_dataset_id
    FOREIGN KEY (dataset_id) REFERENCES dataset (id);

ALTER TABLE human_evaluation
    ADD CONSTRAINT fk_human_evaluation_model_version_id
    FOREIGN KEY (model_version_id) REFERENCES model_version (id);
ALTER TABLE human_evaluation
    ADD CONSTRAINT fk_human_evaluation_direction_id
    FOREIGN KEY (direction_id) REFERENCES translation_direction (id);

-- Un par no puede repetirse dentro de la misma dirección, ignorando
-- mayúsculas/minúsculas y espacios exteriores.
CREATE UNIQUE INDEX IF NOT EXISTS uq_language_pair_direction_source_ci
    ON language_pair (
        source_language_id,
        target_language_id,
        lower(btrim(source_text))
    );

CREATE INDEX IF NOT EXISTS idx_language_pair_direction
    ON language_pair (source_language_id, target_language_id);

COMMIT;
